dz.y = (2.0 * lum(GetPixel(uv3+ver)) - 2.0*lum(GetPixel(uv3-ver).xy));
neu = GetPixel(uv3+dz.yx * 0.0);
ret1 = neu;
dz = dz * 12.0;
vec2 pos = 1;
vec2 uv_rr = sin(2.0 * uv1 + dz*.8 + pos);
