vec2 uv_bb = sin(2.0 * uv1 + dz*1.2 +pos);
vec3 fac = .1;
vec3 mus = vec3(fac.x/length(uv_rr),
fac.y/length(uv_gg),
fac.z/length(uv_bb));
ret = mus -  ret1 *.15 + ret1.g / 2.0;
ret *= 1.0 + ret;
//MilkDrop3 Color Mode:
ret /= vec3(0.7,2.0,0.4);
  fragColor = vec4(ret, 1.0);
}

